using UnityEngine;

namespace DerbyArena.World
{
    /// <summary>
    /// Material factory. Clones template materials from Resources/Derby/Materials (generated by the
    /// Editor build setup) so every shader variant is compiled into the player build.
    /// </summary>
    public static class Mats
    {
        static Texture2D softTex;

        static Material Make(string template, params string[] fallbackShaders)
        {
            var t = Resources.Load<Material>("Derby/Materials/" + template);
            if (t != null) return new Material(t);
            for (int i = 0; i < fallbackShaders.Length; i++)
            {
                Shader s = Shader.Find(fallbackShaders[i]);
                if (s != null)
                {
                    Debug.LogWarning("DERBY: material template '" + template + "' missing; using shader " + s.name);
                    return new Material(s);
                }
            }
            Debug.LogError("DERBY: material template '" + template + "' missing and no fallback shader exists.");
            return null;
        }

        static void SetColor(Material m, string prop, Color c) { if (m != null && m.HasProperty(prop)) m.SetColor(prop, c); }
        static void SetFloat(Material m, string prop, float v) { if (m != null && m.HasProperty(prop)) m.SetFloat(prop, v); }
        static void SetTex(Material m, string prop, Texture t) { if (m != null && t != null && m.HasProperty(prop)) m.SetTexture(prop, t); }

        public static Material Lit(Color albedo, float rough, float metal, Color emission, float energy)
        {
            var mat = Make(energy > 0f ? "RuntimeLitEmissive" : "RuntimeLit", "Standard", "Legacy Shaders/Diffuse", "Sprites/Default");
            if (mat == null) return null;
            SetColor(mat, "_Color", albedo);
            SetFloat(mat, "_Glossiness", 1f - rough);
            SetFloat(mat, "_Metallic", Mathf.Min(metal, 0.5f));
            if (energy > 0f)
            {
                mat.EnableKeyword("_EMISSION");
                SetColor(mat, "_EmissionColor", emission * energy);
            }
            return mat;
        }

        public static Material Glow(Color color, float energy)
        {
            return Lit(new Color(color.r * 0.25f, color.g * 0.25f, color.b * 0.25f, 1f), 0.5f, 0f, color, energy);
        }

        public static Material Textured(Texture2D albedo, Color tint, float smooth, float metal)
        {
            var mat = Make("RuntimeLit", "Standard", "Legacy Shaders/Diffuse", "Sprites/Default");
            if (mat == null) return null;
            SetColor(mat, "_Color", tint);
            SetTex(mat, "_MainTex", albedo);
            SetFloat(mat, "_Glossiness", smooth);
            SetFloat(mat, "_Metallic", Mathf.Min(metal, 0.5f));
            return mat;
        }

        public static Material TexturedNormal(Texture2D albedo, Texture2D normal, Color tint, float smooth, float metal)
        {
            if (normal == null) return Textured(albedo, tint, smooth, metal);
            var mat = Make("RuntimeLitNormal", "Standard", "Legacy Shaders/Diffuse", "Sprites/Default");
            if (mat == null) return null;
            SetColor(mat, "_Color", tint);
            SetTex(mat, "_MainTex", albedo);
            SetTex(mat, "_BumpMap", normal);
            SetFloat(mat, "_BumpScale", 1f);
            SetFloat(mat, "_Glossiness", smooth);
            SetFloat(mat, "_Metallic", Mathf.Min(metal, 0.5f));
            return mat;
        }

        public static Material Glass(Color color)
        {
            var mat = Make("RuntimeLitGlass", "Standard", "Legacy Shaders/Diffuse", "Sprites/Default");
            if (mat == null) return null;
            SetColor(mat, "_Color", color);
            SetFloat(mat, "_Glossiness", 0.88f);
            SetFloat(mat, "_Metallic", 0f);
            return mat;
        }

        public static Texture2D SoftTexture()
        {
            if (softTex != null) return softTex;
            const int size = 64;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, false);
            tex.wrapMode = TextureWrapMode.Clamp;
            tex.filterMode = FilterMode.Bilinear;
            var px = new Color32[size * size];
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float dx = (x + 0.5f) / size * 2f - 1f;
                    float dy = (y + 0.5f) / size * 2f - 1f;
                    float a = Mathf.Clamp01(1f - Mathf.Sqrt(dx * dx + dy * dy));
                    a = a * a * (3f - 2f * a);
                    px[y * size + x] = new Color32(255, 255, 255, (byte)(a * 255f));
                }
            }
            tex.SetPixels32(px);
            tex.Apply(false, true);
            softTex = tex;
            return softTex;
        }

        /// <summary>Alpha blended soft particle / line material.</summary>
        public static Material FxSoft()
        {
            var mat = Make("RuntimeFx", "Sprites/Default");
            if (mat == null) return null;
            SetTex(mat, "_MainTex", SoftTexture());
            return mat;
        }

        /// <summary>Additive glow material (sparks, fire, tracers). Falls back to alpha blending.</summary>
        public static Material FxAdditive()
        {
            var t = Resources.Load<Material>("Derby/Materials/RuntimeFxAdd");
            if (t == null) return FxSoft();
            var mat = new Material(t);
            SetColor(mat, "_TintColor", new Color(0.5f, 0.5f, 0.5f, 0.5f));
            SetTex(mat, "_MainTex", SoftTexture());
            return mat;
        }

        /// <summary>Vertex-colour lit material (robot crowd). Falls back to the plain lit template.</summary>
        public static Material VertexLit(Color tint, float smooth, float metal)
        {
            var t = Resources.Load<Material>("Derby/Materials/RuntimeVertexLit");
            Material mat = null;
            if (t != null && t.shader != null && t.shader.isSupported) mat = new Material(t);
            if (mat == null) mat = Make("RuntimeLit", "Standard", "Legacy Shaders/Diffuse", "Sprites/Default");
            if (mat == null) return null;
            SetColor(mat, "_Color", tint);
            SetFloat(mat, "_Glossiness", smooth);
            SetFloat(mat, "_Metallic", Mathf.Min(metal, 0.5f));
            return mat;
        }

        /// <summary>Dark soft blob used as a contact shadow under vehicles.</summary>
        public static Material BlobShadow()
        {
            var mat = Make("RuntimeFx", "Sprites/Default");
            if (mat == null) return null;
            SetTex(mat, "_MainTex", SoftTexture());
            SetColor(mat, "_Color", new Color(0f, 0f, 0f, 0.62f));
            return mat;
        }

        /// <summary>2.1 sky (DerbyArena/Sky): gradient, sun or moon, cloud panorama, stars. Null when the shader/material is missing.</summary>
        public static Material ThemedSky(Atmosphere.Theme t, Vector3 sunDir)
        {
            var template = Resources.Load<Material>("Derby/Materials/RuntimeSky2");
            if (template == null || template.shader == null || !template.shader.isSupported) return null;
            var mat = new Material(template);
            SetColor(mat, "_ZenithColor", t.Zenith);
            SetColor(mat, "_HorizonColor", t.Horizon);
            SetColor(mat, "_GroundColor", t.SkyGroundColor);
            SetColor(mat, "_SunColor", t.SunColor);
            if (mat.HasProperty("_SunDir")) mat.SetVector("_SunDir", new Vector4(sunDir.x, sunDir.y, sunDir.z, 0f));
            SetFloat(mat, "_SunSize", t.SunSize);
            SetFloat(mat, "_SunGlow", t.SunGlow);
            SetFloat(mat, "_Haze", t.Haze);
            SetColor(mat, "_CloudColor", t.CloudLit);
            SetColor(mat, "_CloudShadow", t.CloudShadow);
            SetFloat(mat, "_CloudDensity", t.CloudDensity);
            SetFloat(mat, "_CloudSpeed", 0.004f);
            SetFloat(mat, "_Stars", t.Stars);
            SetFloat(mat, "_Exposure", t.SkyExposure);
            var clouds = Resources.Load<Texture2D>("Derby/Textures/clouds");
            if (clouds != null) { clouds.wrapMode = TextureWrapMode.Repeat; SetTex(mat, "_CloudTex", clouds); }
            return mat;
        }

        /// <summary>Procedural sky; null when the template is missing (camera falls back to a flat colour).</summary>
        public static Material Sky(Color tint, Color ground, float exposure, float thickness)
        {
            var t = Resources.Load<Material>("Derby/Materials/RuntimeSky");
            if (t == null) return null;
            var mat = new Material(t);
            SetColor(mat, "_SkyTint", tint);
            SetColor(mat, "_GroundColor", ground);
            SetFloat(mat, "_Exposure", exposure);
            SetFloat(mat, "_AtmosphereThickness", thickness);
            SetFloat(mat, "_SunSize", 0.03f);
            return mat;
        }
    }
}
